# Disclaimer: This code is purely for educational purposes and should not be used for any unauthorized or malicious activities. Any use of this code for unethical purposes is strictly prohibited.

import hashlib
import itertools

# Function to generate SHA256 hash with salt
def generate_hash(plain_text, salt):
    return hashlib.sha256(plain_text.encode('utf-8') + salt.encode('utf-8')).hexdigest()

# Generate dictionary of words
dictionary = ['apple', 'banana', 'orange', 'grape', 'pineapple']

# Generate list of possible salts
salts = ['123', '456', '789']

# Generate precomputed hash mappings
hash_mappings = {}
for word in dictionary:
    for salt in salts:
        for permutation in itertools.permutations(word):
            plain_text = ''.join(permutation)
            hash_value = generate_hash(plain_text, salt)
            hash_mappings[hash_value] = plain_text

# Print precomputed hash mappings
for hash_value, plain_text in hash_mappings.items():
    print(f'{hash_value}: {plain_text}')

# Store precomputed hash mappings in a file for future usage
with open('hash_mappings.txt', 'w') as file:
    for hash_value, plain_text in hash_mappings.items():
        file.write(f'{hash_value}: {plain_text}\n')

